import subprocess

def tm(seq):
    r = subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500', seq], capture_output=True, text=True)
    return float(r.stdout.strip())

up = 'gggtctagaaataattttgtttaactttaagaaggagatatacatatgag'
down = 'caagggcgaggagctgttcaccggggtggtgcccatcctggtcgagctgg'
ins = 'tagattagaagaagaattaagaagaagattaacagaaag'

def revcomp(s):
    comp = {'a':'t','t':'a','g':'c','c':'g'}
    return ''.join(comp[c] for c in s[::-1])

results = []
for f in range(15,46):
    for r in range(15,46):
        fa = up[-f:]
        ra = down[:r]
        tf = tm(fa)
        tr = tm(ra)
        if 58 <= tf <= 72 and 58 <= tr <= 72 and abs(tf-tr) <= 5:
            results.append((f,r,tf,tr))
            break
    else:
        continue
    break

if results:
    f,r,tf,tr = results[0]
    fa = up[-f:]
    ra = down[:r]
    print('forward anneal', f, 'tm', tf)
    print('reverse anneal', r, 'tm', tr)
    print('forward primer', ins + fa)
    print('reverse primer', revcomp(ins) + revcomp(ra))
else:
    print('no combo found')
